// Zella - Assistant Tools: Vapi calls this during a call (1) when the assistant could not answer a question
// (report_unanswered_question) or (2) when the caller wants to complain, correct their details, or ask to see or
// remove their data (log_customer_request). Neither tool changes or releases any customer data.
// Runs once for the whole request and returns ONE ITEM PER TOOL CALL, each with its own tool call id and its own
// answer. Invalid customer-request arguments return an error before any logging RPC. Other non-loggable reports
// are sent as an empty question, which the database refuses. Nothing is run as instructions.
// @ts-self-types="./vapi-brain-tools.d.ts"
// Receptionist Brain tools: one Vapi tool call -> one call to the audited gateway zella_ai_tool, and its answer back.
// ONE implementation, used by the voice-rules edge function (import) and by n8n Brain Tools (inlined at build time by
// n8n/src/load.mjs, `export` removed). No network, no secrets. Every decision (business, confirmation, spam screening,
// availability, locks, idempotency, verification, audit) is made by zella_ai_tool in the database; this only checks
// the shape of the arguments, keeps known fields, and takes the caller's number from the phone network.

// The tools the database defines (zella_brain_tool_defs). Anything else is answered "not something you can do".
const TOOLS = ['search_knowledge', 'check_open_hours', 'lookup_caller', 'update_caller', 'check_availability', 'book_appointment', 'find_my_appointments',
  'reschedule_appointment', 'cancel_appointment', 'take_message', 'report_emergency', 'transfer_to_human', 'request_follow_up', 'report_unanswered_question',
  'lookup_order'];
const BRAIN_TOOLS = TOOLS;
const BOOKING_TOOLS = ['check_availability', 'book_appointment', 'find_my_appointments', 'reschedule_appointment', 'cancel_appointment'];
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const STRINGS = ['query', 'appointment_id', 'date', 'start', 'first_name', 'last_name', 'phone', 'email', 'title', 'notes', 'name', 'message',
  'preferred_contact_method', 'reason', 'when', 'summary', 'question', 'order_number', 'seating'];
const NUMBERS = ['days', 'duration_minutes', 'party_size'];
const isObj = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
const o = (v) => (isObj(v) ? v : {});

// Who is calling, which line, which call: from Vapi's call object only (never from what is said).
function vapiCallContext(message) {
  const m = o(message);
  const call = o(m.call);
  const meta = o(call.metadata);
  const pn = isObj(call.phoneNumber) ? call.phoneNumber : o(m.phoneNumber);
  const cn = String(o(call.customer).number || '');
  // the assistant's own metadata (set by Zella Voice when the assistant is configured) also counts: web test calls have no
  // phone number and no call metadata. The call's variable values are NOT used: whoever starts a web call can set
  // them, so a business id there could point the tools at another business. Zella Voice never puts one there.
  const asst = o(o(m.assistant).metadata);
  const bid = [meta.business_id, asst.business_id].find((v) => typeof v === 'string' && UUID.test(v)) || null;
  return {
    callId: typeof call.id === 'string' && call.id ? call.id.slice(0, 200) : null,
    calledNumber: typeof pn.number === 'string' && /^\+?[0-9() .-]{7,20}$/.test(pn.number) ? pn.number : null,
    vapiNumberId: typeof call.phoneNumberId === 'string' ? call.phoneNumberId.slice(0, 100) : typeof pn.id === 'string' ? pn.id.slice(0, 100) : null,
    callerNumber: /^\+?[0-9]{7,15}$/.test(cn) ? cn : null,
    // only a fallback: a registered number always wins (zella_business_for_number), and zella_ai_tool prefers the call's own business
    fallbackBusinessId: bid,
  };
}

const toolName = (tc) => String((tc && (tc.name || (tc.function && tc.function.name))) || '').slice(0, 80);

function toolArgs(tc) {
  let args = tc && tc.arguments !== undefined ? tc.arguments : tc && tc.function && tc.function.arguments;
  if (typeof args === 'string') { try { args = JSON.parse(args); } catch (_e) { args = {}; } }
  return o(args);
}

// Shape checks. A value that is present but malformed is refused with a clear instruction instead of being guessed at;
// the database still checks meaning (availability, ownership, email format, need for a name).
function invalidField(clean) {
  if (clean.date !== undefined && (!/^\d{4}-\d{2}-\d{2}$/.test(clean.date) || Number.isNaN(Date.parse(clean.date + 'T00:00:00Z')))) return 'date must be YYYY-MM-DD';
  if (clean.start !== undefined && (Number.isNaN(Date.parse(clean.start)) || !/[T ]\d{2}:\d{2}/.test(clean.start))) return 'start must be a time exactly as returned by check_availability';
  if (clean.appointment_id !== undefined && !UUID.test(clean.appointment_id)) return 'appointment_id must come from find_my_appointments';
  if (clean.days !== undefined && !(Number.isInteger(clean.days) && clean.days >= 1 && clean.days <= 14)) return 'days must be a whole number from 1 to 14';
  if (clean.duration_minutes !== undefined && !(Number.isInteger(clean.duration_minutes) && clean.duration_minutes >= 5 && clean.duration_minutes <= 480)) return 'duration_minutes must be a whole number from 5 to 480';
  if (clean.preferred_contact_method !== undefined && !['call', 'sms', 'email'].includes(clean.preferred_contact_method)) return 'preferred_contact_method must be call, sms or email';
  if (clean.email !== undefined && clean.email.length > 200) return 'email is too long';
  if (clean.party_size !== undefined && !(Number.isInteger(clean.party_size) && clean.party_size >= 1 && clean.party_size <= 999)) return 'party_size must be a whole number of people from 1 to 999';
  if (clean.seating !== undefined && clean.seating.length > 40) return 'seating must be a short preference, e.g. patio';
  if (clean.order_number !== undefined && !/^#?[A-Za-z0-9-]{1,30}$/.test(clean.order_number)) return 'order_number must be the order number only, e.g. 1001';
  return null;
}

// One tool call -> { toolCallId, name, invalid, record }. record = the zella_ai_tool arguments (p_business_id filled in
// by the caller of this function from the number lookup). An unknown tool or bad arguments still gets a record with
// p_tool 'unknown', so a workflow that can only send everything to the database stays on one path; the database then
// refuses without acting. The edge function does not send those at all.
function planBrainTool(tc, ctx, allowed = TOOLS) {
  const name = toolName(tc);
  const args = toolArgs(tc);
  const usesSeating = ['check_availability', 'book_appointment'].includes(name);
  const malformedSeating = usesSeating && Object.hasOwn(args, 'seating') && typeof args.seating !== 'string';
  const clean = {};
  for (const k of STRINGS) if (typeof args[k] === 'string') clean[k] = args[k].replace(/\s+/g, ' ').trim().slice(0, k === 'query' ? 300 : 1500);
  for (const k of NUMBERS) if (typeof args[k] === 'number' && Number.isFinite(args[k])) clean[k] = args[k];
  if (!usesSeating) delete clean.seating;
  // the caller's yes must be a real boolean from the assistant; anything else counts as "not confirmed"
  clean.confirmed = args.confirmed === true;
  const known = TOOLS.includes(name) && allowed.includes(name);
  const typeError = malformedSeating ? 'seating must be a string preference'
    : Object.hasOwn(args, 'party_size') && (typeof args.party_size !== 'number' || !Number.isFinite(args.party_size))
      ? 'party_size must be a whole number of people from 1 to 999' : null;
  const invalid = known ? typeError || invalidField(clean) : null;
  return {
    toolCallId: tc.id, name, known, invalid,
    record: { p_provider_call_id: ctx.callId, p_business_id: ctx.fallbackBusinessId, p_tool: known && !invalid ? name : 'unknown',
              p_args: { ...clean, caller_number: ctx.callerNumber },
              // the tool call id makes a repeated delivery of the same call a no-op (and waits for one still running)
              p_idempotency_key: ctx.callId ? (ctx.callId + ':' + tc.id).slice(0, 300) : null },
  };
}

// The tool calls of one request: those with a usable id, each id once, at most 10.
function toolCallList(message) {
  const m = o(message);
  const list = Array.isArray(m.toolCallList) ? m.toolCallList : Array.isArray(m.toolCalls) ? m.toolCalls : [];
  const out = [];
  const seen = new Set();
  for (const tc of list.slice(0, 10)) {
    if (!isObj(tc) || typeof tc.id !== 'string' || !tc.id || tc.id.length > 200 || seen.has(tc.id)) continue;
    seen.add(tc.id);
    out.push(tc);
  }
  return out;
}

const BRAIN_FAILED = 'This could not be completed right now. Tell the caller the team will call them back. Do not say it was done.';
const BRAIN_UNKNOWN = 'That is not something you can do. Offer to take a message instead.';
const line = (s, n) => String(s).replace(/[\r\n]+/g, ' ').slice(0, n);

// The answer for ONE tool call, in Vapi's ToolCallResult format: { name, toolCallId, result } or { name, toolCallId, error },
// single-line strings. Short, no database details. The transfer number is never given to the model (the system picks it
// on transfer-destination-request). A caller the backend screened out gets the screening instruction instead.
function brainToolReply(name, toolCallId, ok, body) {
  const b = isObj(body) ? body : null;
  if (!ok || !b || typeof b.say !== 'string') return { name, toolCallId, error: BRAIN_FAILED };
  const caller = o(b.caller);
  const scr = o(caller.screening);
  let out;
  if (b.status === 'screened' || (['blocked', 'restricted', 'screened'].includes(scr.decision) && typeof caller.say === 'string')) {
    out = { status: 'screened', instruction: line(b.status === 'screened' ? b.say : caller.say, 600), can_transfer: false };
  } else {
    out = { status: b.status, instruction: line(b.say + (typeof caller.say === 'string' && caller.say ? ' About this caller: ' + caller.say : ''), 900) };
    if (typeof b.open === 'boolean') out.open = b.open;
    if (typeof b.can_transfer === 'boolean') out.can_transfer = b.can_transfer;
    if (b.status === 'transfer') out.use_transfer_tool = true;
    if (scr.decision === 'flagged') out.caution = true;
    if (Array.isArray(b.emergency_keywords)) out.emergency_words = b.emergency_keywords.slice(0, 20);
    if (Array.isArray(b.slots)) out.times = b.slots.slice(0, 5).map((s) => ({ say: o(s).say, start: o(s).start }));
    if (Array.isArray(b.appointments)) out.appointments = b.appointments.slice(0, 3).map((a) => ({ appointment_id: o(a).appointment_id, title: o(a).title, say: o(a).say }));
    if (Array.isArray(b.results)) out.results = b.results.slice(0, 3).map((x) => ({ title: o(x).title, answer: o(x).answer }));
    if (typeof b.first_name === 'string') out.first_name = b.first_name.slice(0, 80);
  }
  return { name, toolCallId, result: JSON.stringify(out) };
}

// An argument problem found before the database was asked: the model is told what to fix.
const brainInvalidReply = (name, toolCallId, why) => ({ name, toolCallId, error: 'Invalid arguments: ' + why + '. Nothing was done.' });

const body = (($input.first() || {}).json || {}).body;
const m = body && typeof body === 'object' && body.message && typeof body.message === 'object' ? body.message : {};
const list = toolCallList(m);
const nameOf = (t) => (t && (t.name || (t.function && t.function.name))) || '';
const ALLOWED_TOOLS = ['report_unanswered_question', 'log_customer_request'];
if (m.type !== 'tool-calls' || !list.length) return [{ json: { reply: { results: [] }, record: null } }];

const ctx = vapiCallContext(m);
const bid = ctx.fallbackBusinessId;
const callId = ctx.callId;
const callerNumber = ctx.callerNumber;
const lookup = { p_called_number: ctx.calledNumber, p_vapi_phone_number_id: ctx.vapiNumberId, p_fallback: bid };
const kinds = ['complaint', 'correction', 'data_access', 'data_deletion'];

const out = [];
const seen = new Set();
for (const tc of list.slice(0, 10)) {
  if (!tc || typeof tc.id !== 'string' || !tc.id || tc.id.length > 200 || seen.has(tc.id)) continue;
  seen.add(tc.id);
  const name = nameOf(tc);
  const isRequest = name === 'log_customer_request';
  const ok = !ALLOWED_TOOLS.includes(name) ? 'This is not something you can do. Offer to take a message instead.'
    : isRequest
      ? 'Noted. Tell the caller the team has been told and will contact them. Do not say anything has been changed, sent or deleted, and do not read out or confirm any personal details.'
      : 'Noted. Tell the caller you will pass the question to the team and they will get back to them.';
  let args = tc.arguments !== undefined ? tc.arguments : tc.function && tc.function.arguments;
  if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
  args = args && typeof args === 'object' && !Array.isArray(args) ? args : {};
  const question = String((isRequest ? args.summary : args.question) || '').replace(/\s+/g, ' ').trim().slice(0, isRequest ? 1000 : 500);
  const kind = typeof args.kind === 'string' ? args.kind.trim().toLowerCase() : '';
  const invalid = isRequest && (typeof args.summary !== 'string' || question.length < 3 || !kinds.includes(kind)) ? 'Invalid arguments: provide a summary of at least 3 characters and a supported kind.' : null;
  const loggable = !invalid && ALLOWED_TOOLS.includes(name) && question.length >= 3 && (!isRequest || kinds.includes(kind));
  out.push({ json: { tool_call_id: tc.id, tool: name.slice(0, 80), reply_text: ok, loggable, lookup, invalid,
    rpc: isRequest ? 'zella_ai_log_request' : 'zella_report_unanswered',
    record: isRequest
      ? { p_provider_call_id: callId, p_business_id: bid, p_kind: kind, p_summary: question }
      : { p_provider_call_id: callId, p_business_id: bid, p_question: loggable ? question : '' } } });
}
return out.length ? out : [{ json: { reply: { results: [] }, record: null } }];

// Zella - Vapi tools: put the business found from the called number into the database call.
// All callers query with p_fallback null: only a trusted registered phone association can return an id.
// Unlinked call settings are rejected. Existing calls are resolved by the acting RPC even with a null business id.
const plan = $('Plan').item.json;
const b = $json.body;
const status = Number($json.statusCode);
const found = status >= 200 && status < 300 && typeof b === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(b) ? b : null;
return { json: { ...plan, record: { ...plan.record, p_business_id: found } } };

// Zella - Assistant Tools: the answer for ONE tool call, under its own toolCallId. It never contains database
// details; a failed write returns an error so the assistant cannot claim the team was notified.
const plan = $('Use business').item.json;
if (plan.invalid) return { json: { name: String(plan.tool || '').slice(0, 80), toolCallId: plan.tool_call_id, error: plan.invalid } };
if (plan.loggable && (!(Number($json.statusCode) >= 200 && Number($json.statusCode) < 300) || (plan.rpc === 'zella_ai_log_request' && $json.body?.ok === false))) return { json: { name: String(plan.tool || '').slice(0, 80), toolCallId: plan.tool_call_id, error: 'The request could not be saved. Offer to try again or take another contact route; do not say the team was notified.' } };
return { json: { name: String(plan.tool || '').slice(0, 80), toolCallId: plan.tool_call_id, result: plan.reply_text } };

// Zella - Vapi webhooks: hand the database the exact request bytes and the signature headers. The database checks the
// signature, the timestamp and that the request is new (zella_vapi_authenticate); the secret never reaches n8n.
// Nothing else in the workflow runs unless the answer is "ok".
const first = $input.first() || { json: {} };
const h = first.json.headers && typeof first.json.headers === 'object' ? first.json.headers : {};
const headers = {};
for (const k of ['x-signature', 'x-timestamp', 'authorization']) if (typeof h[k] === 'string') headers[k] = h[k].slice(0, 1000);
let raw = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
} catch (e) { raw = ''; }
if (raw.length > 262144) raw = '';
return [{ json: { record: { p_raw: raw, p_headers: headers } } }];
